CREATE EXTENSION IF NOT EXISTS pgcrypto;


INSERT INTO auth.role (
    id,
    name
)
VALUES (
    gen_random_uuid(),
    'ADMIN'
)
ON CONFLICT (name) DO NOTHING;


-- ADMIN IDENTITY
-- password: 1234
-- BCrypt generated by PostgreSQL pgcrypto
INSERT INTO auth.identity (
    id,
    username,
    email,
    password_hash,
    email_verified,
    phone_verified,
    is_active,
    is_blocked,
    person_id
)
VALUES (
    gen_random_uuid(),
    'admin',
    'admin@chemxr.local',
    crypt('1234', gen_salt('bf', 12)),
    TRUE,
    FALSE,
    TRUE,
    FALSE,
    gen_random_uuid()
)
ON CONFLICT (username) DO NOTHING;

-- ADMIN -> ADMIN ROLE
INSERT INTO auth.identity_role (
    identity_id,
    role_id
)
SELECT
    i.id,
    r.id
FROM auth.identity i
CROSS JOIN auth.role r
WHERE i.username = 'admin'
  AND r.name = 'ADMIN'
ON CONFLICT (identity_id, role_id) DO NOTHING;


-- ============================================================
-- OAUTH2 CLIENT
--
-- client_id:     chemxr-client
-- client_secret: bonjour
--
-- Supported:
--   client_credentials
--   password (custom grant)
--
-- Scope:
--   api.read
-- ============================================================
INSERT INTO auth.oauth2_registered_client (
    id,
    client_id,
    client_id_issued_at,
    client_secret,
    client_name,
    client_authentication_methods,
    authorization_grant_types,
    redirect_uris,
    post_logout_redirect_uris,
    scopes,
    client_settings,
    token_settings
)
VALUES (
    gen_random_uuid()::text,
    'chemxr-client',
    CURRENT_TIMESTAMP,
    crypt('bonjour', gen_salt('bf', 12)),
    'ChemXR Client',
    'client_secret_basic',
    'client_credentials,password',
    NULL,
    NULL,
    'api.read',
    '{"@class":"java.util.Collections$UnmodifiableMap"}',
    '{"@class":"java.util.Collections$UnmodifiableMap"}'
)
ON CONFLICT (client_id) DO NOTHING;
